import {spiralCase,spiralAnimal} from './living-spiral-content.mjs';
import {spiralState} from './living-spiral-core.mjs';
import {connectionNames,learningSource,connectionOffers,connectionAvailability,startConnection,activeConnection,connectionRecords} from './learning-connections.mjs';
import {validConnection} from './learning-connection-data.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href={living:'#living',cafe:'#cafe',bramble:'#post'};
const quantities=(a,b)=>`${a} groups of ${b}`;
export function connectionReason(c){return c.proposal==='positive'?'Our zero-pack plan can lead to a different question: what changes if we send one pack?':c.outcome==='retry'?'That task needed another try. Let’s try the same idea with new things to count.':c.outcome==='supported'?'We explored that idea with support. Let’s try the same idea in another place.':c.outcome==='explored'?'We have explored this idea. Let’s try it with new things to count.':'That fit! Let’s try a close cousin of that problem somewhere new.';}
function sourceText(c){return `${connectionNames[c.source]} · ${c.relation==='inverse'?'finding the pack count':c.relation==='tomorrow'?'tomorrow’s plan':'equal groups'} · ${quantities(c.sourceA,c.sourceB)}`;}
function groupArt(c,target){const label=target==='cafe'?'plates':target==='bramble'?'bundles':'packs';return `<div class="connection-picture" role="img" aria-label="${c.a} ${label}, ${c.b} in each"><div aria-hidden="true">${Array.from({length:c.a},()=>`<span>${Array.from({length:c.b},()=>'<i></i>').join('')}</span>`).join('')}</div><p>${c.a} ${label} · ${c.b} in each</p></div>`;}
function cafePrompts(state){const r=spiralState(state)?.current;if(!r||r.revision!=='habitat-round-2'||!r.inspected.length)return '';const a=spiralAnimal(spiralCase(r.task.caseId).animal);return `<details class="connection-talk"><summary>Bring our nature clues and reading to the table</summary><p>In the garden, we checked ${esc(a.need.replace(/^Find /,'').toLowerCase().replace(/\.$/,''))}. Animal needs and our imaginary guests’ food preferences are different. Which ingredient qualities match this guest’s wishes? What clue supports our choice?</p><p>Read the guest’s request together. Point to the words that tell us what to put on a plate. What should we do first, and next?</p><p class="tiny">Pretend café food is only for pretend guests.</p></details>`;}
export function connectionPanel(state,target){if(!href[target])return '';const incoming=connectionOffers(state,target),outgoing=learningSource(state,target),active=activeConnection(state,target);if(!incoming.length&&!outgoing&&!active&&target!=='cafe')return '';
 const blocked=connectionAvailability(state,target);return `<section class="learning-connections panel" aria-labelledby="connection-heading"><p class="place-name">One garden · Many ways to use an idea</p><h2 id="connection-heading">Carry an idea here</h2>${active?`<p class="connection-active">This task carries an idea from ${esc(sourceText(active))}. Here we’re using ${quantities(active.a,active.b)}. ${esc(connectionReason(active))}</p>`:''}${incoming.length?`<div class="connection-grid">${incoming.map(c=>`<article><p class="place-name">From ${esc(connectionNames[c.source])}</p><h3>${target==='cafe'?'A table to feed':target==='bramble'?'Ribbons for the recovery path':'A connected parcel to find'}</h3><p>${esc(sourceText(c))}.</p><p>${esc(connectionReason(c))}</p>${c.relation==='inverse'?'<p class="tiny">Last time you found how many packs. This time, find how many in all.</p>':''}${groupArt(c,target)}${blocked?`<p class="status-note">${esc(blocked)}</p><a href="${target==='living'&&spiralState(state)?.current?'#living/visit':href[target]}" class="secondary">${target==='bramble'&&!state.postOffice?.current?'Choose a delivery':'Continue our waiting activity'}</a>`:`<button type="button" class="primary" data-connection-start="${c.source}" data-connection-target="${target}">${target==='cafe'?`Invite ${c.a} guests · ${c.b} bites each`:target==='bramble'?`Try ${c.a} bundles · ${c.b} ribbons each`:`Search for ${c.a} equal packs · ${c.b} bites each`}</button>`}</article>`).join('')}</div>`:'<p>A finished parcel, café total or Bramble puzzle can offer a related task here. Ordinary play stays open.</p>'}${outgoing?`<div class="connection-outgoing"><h3>Take our ${quantities(outgoing.sourceA,outgoing.sourceB)} idea somewhere else</h3><div class="summary-links">${Object.keys(href).filter(k=>k!==target).map(k=>`<a class="secondary" href="${href[k]}">Visit ${esc(connectionNames[k])}</a>`).join('')}</div><p class="tiny">An idea will be waiting for you there.</p></div>`:''}${target==='cafe'?cafePrompts(state):''}<details class="connection-talk"><summary>Grown-ups: how the connection is chosen</summary><p>Each source keeps its own recent notebook. Retries, recorded support or a previously supplied result invite the same relationship; a first-response match without those qualifiers can invite a neighboring fact. Familiarity may be unknown in older café/Bramble work. These are practice suggestions, not mastery or independent-recall evidence. Source answers are never copied into another game’s observations. New tasks record their own actual responses and help. Table/range preferences stay unchanged; a connected garden parcel uses a one-off equal-packs form.</p><p>Each offer is one chosen task, and the usual number choices stay the same. A connected garden parcel uses equal-pack counting; nature and note trails keep their own suggestions. A connection offer waits in another game while its source remains in this notebook.${target==='cafe'?' Talking prompts about nature clues and reading are unscored and are kept apart from habitat or reading observations. Pretend café food is different from wildlife food.':''}</p></details></section>`;}
export function connectionNotes(state){const rs=connectionRecords(state);return `<details class="panel"><summary>Ideas carried between games (${rs.length} retained tasks)</summary><p>Frozen provenance on each destination task. Original source records may age out of their bounded histories. These connections do not copy attempts or certify transfer; reading/nature discussions are unscored. Café support is a conservative whole-total-task flag; audio/method may be unobserved.</p>${rs.map(r=>`<section><h3>${esc(connectionNames[r.target])} · task ${r.id}</h3>${validConnection(r.c)?`<p>From ${esc(sourceText(r.c))}, local source ID ${r.c.sourceId}. Source outcome: ${r.c.outcome}; familiarity: ${r.c.familiarity}. Target: ${quantities(r.c.a,r.c.b)}. ${esc(connectionReason(r.c))}</p>`:'<p>Unknown connection metadata retained without an invitation.</p>'}<pre>${esc(JSON.stringify(r.c,null,2))}</pre></section>`).join('')}</details>`;}
export function bindConnections(state,{save,render,navigate,focus,isCurrent=()=>true}){document.querySelectorAll('[data-connection-start]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||!isCurrent())return;const target=b.dataset.connectionTarget;if(startConnection(state,target,b.dataset.connectionStart)){save();navigate(target==='living'?'#living/visit':href[target]);focus?.(target==='living'?'h1':target==='bramble'?'#post-rival-title':'#cafe-work-title');}else{render();focus?.('#connection-heading');}}));}
